// rate_limiting.rs - Rate Limiting Implementation
use std::collections::HashMap;\use std::sync::Arc;\use std::time::{Duration, Instant};\use tokio::sync::{RwLock, Mutex};\use tokio::time::interval;\use serde::{Deserialize, Serialize};\use thiserror::Error;

#[derive(Error, Debug)]
pub enum RateLimitError {
    #[error("Rate limit exceeded: {limit} requests per {window:?}")]
    LimitExceeded { limit: u32, window: Duration },
    #[error("Invalid configuration: {0}")]
    InvalidConfig(String),
    #[error("Storage error: {0}")]
    StorageError(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RateLimitPolicy {
    pub name: String,
    pub algorithm: Algorithm,
    pub max_requests: u32,
    pub window: Duration,
    pub block_duration: Option<Duration>,
    pub key_prefix: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Algorithm {
    TokenBucket,
    SlidingWindow,
    FixedWindow,
    SlidingWindowLog,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RateLimitResult {
    pub allowed: bool,
    pub remaining: u32,
    pub reset_at: Option<Instant>,
    pub retry_after: Option<Duration>,
}

#[derive(Debug)]
struct TokenBucket {
    capacity: u32,
    tokens: f64,
    refill_rate: f64,
    last_refill: Instant,
}

impl TokenBucket {
    fn new(capacity: u32, refill_rate: f64) -> Self {
        Self {
            capacity,
            tokens: capacity as f64,
            refill_rate,
            last_refill: Instant::now(),
        }
    }

    fn try_consume(&mut self, tokens: u32) -> bool {
        self.refill();
        if self.tokens >= tokens as f64 {
            self.tokens -= tokens as f64;
            true
        } else {
            false
        }
    }

    fn refill(&mut self) {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_refill).as_secs_f64();
        self.tokens = (self.tokens + elapsed * self.refill_rate).min(self.capacity as f64);
        self.last_refill = now;
    }

    fn remaining(&self) -> u32 {
        self.tokens.floor() as u32
    }

    fn reset_after(&self) -> Duration {
        if self.tokens >= self.capacity as f64 {
            Duration::ZERO
        } else {
            Duration::from_secs_f64((self.capacity as f64 - self.tokens) / self.refill_rate)
        }
    }
}

#[derive(Debug)]
struct SlidingWindow {
    max_requests: u32,
    window: Duration,
    requests: Vec<Instant>,
}

impl SlidingWindow {
    fn new(max_requests: u32, window: Duration) -> Self {
        Self {
            max_requests,
            window,
            requests: Vec::new(),
        }
    }

    fn try_consume(&mut self) -> bool {
        let now = Instant::now();
        let cutoff = now - self.window;
        self.requests.retain(|&t| t > cutoff);

        if self.requests.len() < self.max_requests as usize {
            self.requests.push(now);
            true
        } else {
            false
        }
    }

    fn remaining(&self) -> u32 {
        let now = Instant::now();
        let cutoff = now - self.window;
        let count = self.requests.iter().filter(|&&t| t > cutoff).count();
        self.max_requests.saturating_sub(count as u32)
    }

    fn reset_after(&self) -> Duration {
        if self.requests.is_empty() {
            Duration::ZERO
        } else {
            let oldest = *self.requests.iter().min().unwrap();
            (oldest + self.window).saturating_duration_since(Instant::now())
        }
    }
}

pub struct RateLimiter {
    policies: HashMap<String, RateLimitPolicy>,
    token_buckets: Arc<RwLock<HashMap<String, TokenBucket>>>,
    sliding_windows: Arc<RwLock<HashMap<String, SlidingWindow>>>,
    blocked_keys: Arc<RwLock<HashMap<String, Instant>>>,
    cleanup_interval: Duration,
}

impl RateLimiter {
    pub fn new(policies: Vec<RateLimitPolicy>) -> Result<Self, RateLimitError> {
        let mut policy_map = HashMap::new();
        for policy in policies {
            if policy.max_requests == 0 {
                return Err(RateLimitError::InvalidConfig("max_requests must be > 0".to_string()));
            }
            if policy.window == Duration::ZERO {
                return Err(RateLimitError::InvalidConfig("window must be > 0".to_string()));
            }
            policy_map.insert(policy.name.clone(), policy);
        }

        Ok(Self {
            policies: policy_map,
            token_buckets: Arc::new(RwLock::new(HashMap::new())),
            sliding_windows: Arc::new(RwLock::new(HashMap::new())),
            blocked_keys: Arc::new(RwLock::new(HashMap::new())),
            cleanup_interval: Duration::from_secs(60),
        })
    }

    pub async fn check_limit(&self, policy_name: &str, key: &str) -> Result<RateLimitResult, RateLimitError> {
        let policy = self.policies.get(policy_name)
            .ok_or_else(|| RateLimitError::InvalidConfig(format!("Policy '{}' not found", policy_name)))?;

        let full_key = format!("{}:{}", policy.key_prefix, key);

        if let Some(blocked_until) = self.blocked_keys.read().await.get(&full_key) {
            if Instant::now() < *blocked_until {
                return Ok(RateLimitResult {
                    allowed: false,
                    remaining: 0,
                    reset_at: Some(*blocked_until),
                    retry_after: Some(blocked_until.saturating_duration_since(Instant::now())),
                });
            } else {
                self.blocked_keys.write().await.remove(&full_key);
            }
        }

        let result = match policy.algorithm {
            Algorithm::TokenBucket => self.check_token_bucket(policy, &full_key).await,
            Algorithm::SlidingWindow => self.check_sliding_window(policy, &full_key).await,
            Algorithm::FixedWindow => self.check_fixed_window(policy, &full_key).await,
            Algorithm::SlidingWindowLog => self.check_sliding_window_log(policy, &full_key).await,
        };

        if !result.allowed {
            if let Some(block_duration) = policy.block_duration {
                self.blocked_keys.write().await.insert(full_key, Instant::now() + block_duration);
            }
        }

        Ok(result)
    }

    async fn check_token_bucket(&self, policy: &RateLimitPolicy, key: &str) -> RateLimitResult {
        let mut buckets = self.token_buckets.write().await;
        let bucket = buckets.entry(key.to_string()).or_insert_with(||
            TokenBucket::new(policy.max_requests, policy.max_requests as f64 / policy.window.as_secs_f64())
        );

        let allowed = bucket.try_consume(1);
        RateLimitResult {
            allowed,
            remaining: bucket.remaining(),
            reset_at: if allowed { None } else { Some(Instant::now() + bucket.reset_after()) },
            retry_after: if allowed { None } else { Some(bucket.reset_after()) },
        }
    }

    async fn check_sliding_window(&self, policy: &RateLimitPolicy, key: &str) -> RateLimitResult {
        let mut windows = self.sliding_windows.write().await;
        let window = windows.entry(key.to_string()).or_insert_with(||
            SlidingWindow::new(policy.max_requests, policy.window)
        );

        let allowed = window.try_consume();
        RateLimitResult {
            allowed,
            remaining: window.remaining(),
            reset_at: if allowed { None } else { Some(Instant::now() + window.reset_after()) },
            retry_after: if allowed { None } else { Some(window.reset_after()) },
        }
    }

    async fn check_fixed_window(&self, policy: &RateLimitPolicy, key: &str) -> RateLimitResult {
        let mut windows = self.sliding_windows.write().await;
        let now = Instant::now();
        let window_key = format!("{}:{}", key, now.as_secs() / policy.window.as_secs());

        let window = windows.entry(window_key).or_insert_with(||
            SlidingWindow::new(policy.max_requests, policy.window)
        );

        let allowed = window.try_consume();
        RateLimitResult {
            allowed,
            remaining: window.remaining(),
            reset_at: if allowed { None } else { Some(Instant::now() + window.reset_after()) },
            retry_after: if allowed { None } else { Some(window.reset_after()) },
        }
    }

    async fn check_sliding_window_log(&self, policy: &RateLimitPolicy, key: &str) -> RateLimitResult {
        self.check_sliding_window(policy, key).await
    }

    pub async fn start_cleanup_task(&self) {
        let token_buckets = self.token_buckets.clone();
        let sliding_windows = self.sliding_windows.clone();
        let blocked_keys = self.blocked_keys.clone();
        let interval = self.cleanup_interval;

        tokio::spawn(async move {
            let mut ticker = interval(interval);
            loop {
                ticker.tick().await;
                let now = Instant::now();

                let mut buckets = token_buckets.write().await;
                buckets.retain(|_, bucket| {
                    bucket.refill();
                    bucket.tokens > 0.0 || now.duration_since(bucket.last_refill) < Duration::from_secs(300)
                });

                let mut windows = sliding_windows.write().await;
                windows.retain(|_, window| {
                    let cutoff = now - window.window;
                    window.requests.retain(|&t| t > cutoff);
                    !window.requests.is_empty()
                });

                let mut blocked = blocked_keys.write().await;
                blocked.retain(|_, &mut until| until > now);
            }
        });
    }

    pub fn get_policy(&self, name: &str) -> Option<&RateLimitPolicy> {
        self.policies.get(name)
    }

    pub fn list_policies(&self) -> Vec<&RateLimitPolicy> {
        self.policies.values().collect()
    }
}

impl Default for RateLimiter {
    fn default() -> Self {
        Self::new(vec![
            RateLimitPolicy {
                name: "api".to_string(),
                algorithm: Algorithm::TokenBucket,
                max_requests: 100,
                window: Duration::from_secs(60),
                block_duration: Some(Duration::from_secs(300)),
                key_prefix: "api".to_string(),
            },
            RateLimitPolicy {
                name: "login".to_string(),
                algorithm: Algorithm::SlidingWindow,
                max_requests: 5,
                window: Duration::from_secs(300),
                block_duration: Some(Duration::from_secs(900)),
                key_prefix: "auth".to_string(),
            },
            RateLimitPolicy {
                name: "strict".to_string(),
                algorithm: Algorithm::SlidingWindowLog,
                max_requests: 10,
                window: Duration::from_secs(60),
                block_duration: Some(Duration::from_secs(60)),
                key_prefix: "strict".to_string(),
            },
        ]).unwrap()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tokio::time::sleep;

    #[tokio::test]
    async fn test_token_bucket_allows_burst() {
        let limiter = RateLimiter::new(vec![
            RateLimitPolicy {
                name: "test".to_string(),
                algorithm: Algorithm::TokenBucket,
                max_requests: 10,
                window: Duration::from_secs(60),
                block_duration: None,
                key_prefix: "test".to_string(),
            }
        ]).unwrap();

        for i in 0..10 {
            let result = limiter.check_limit("test", "user1").await.unwrap();
            assert!(result.allowed, "Request {} should be allowed", i);
        }

        let result = limiter.check_limit("test", "user1").await.unwrap();
        assert!(!result.allowed);
    }

    #[tokio::test]
    async fn test_sliding_window_resets() {
        let limiter = RateLimiter::new(vec![
            RateLimitPolicy {
                name: "test".to_string(),
                algorithm: Algorithm::SlidingWindow,
                max_requests: 3,
                window: Duration::from_millis(100),
                block_duration: None,
                key_prefix: "test".to_string(),
            }
        ]).unwrap();

        for _ in 0..3 {
            assert!(limiter.check_limit("test", "user1").await.unwrap().allowed);
        }
        assert!(!limiter.check_limit("test", "user1").await.unwrap().allowed);

        sleep(Duration::from_millis(150)).await;
        assert!(limiter.check_limit("test", "user1").await.unwrap().allowed);
    }
}
